<template>
  <section v-if="available" class="project-camp-inbox"><header><h3>项目参营与本期名单</h3><DewButton size="sm" type="ghost" @click="load">刷新</DewButton></header><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!rows.length" class="pci-muted">暂无独立项目参营申请。</p><article v-for="row in rows" :key="row.binding.id"><h4>{{ row.project.title }} · {{ labels[row.binding.status] }}</h4><p>{{ (row.binding.requested_users.length?row.binding.requested_users:row.binding.participants).map(m=>m.name).join('、') }}</p><DewButton v-if="row.binding.status==='requested'" size="sm" @click="operate(row,'approve')">批准参营</DewButton><DewButton v-if="row.binding.status==='requested'" size="sm" type="ghost" @click="operate(row,'reject')">拒绝</DewButton><DewButton v-if="row.binding.change_pending" size="sm" @click="operate(row,'participants')">确认名单变更</DewButton><DewButton v-if="row.binding.status==='active'" size="sm" type="ghost" @click="editLeader(row)">调整本期负责人</DewButton><DewButton v-if="row.binding.status==='active'" size="sm" type="ghost" @click="operate(row,'end')">结束本期关联</DewButton><DewButton v-if="row.binding.unit_id" size="sm" type="ghost" @click="open(row)">查看本期项目</DewButton></article><DewDialog v-model="leaderDialog" title="调整本期负责人" width="500px"><DewSelect v-model="leaderId" :options="(selected?.binding.participants||[]).map(m=>({value:m.user_id,label:m.name}))" /><template #footer><DewButton @click="operate(selected,'participants',leaderId)">确认交接</DewButton></template></DewDialog></section>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {DewButton,DewSelect,DewDialog} from '@bme/dew-ui'
import {ElMessage,ElMessageBox} from 'element-plus'
import {projectService,mutation} from './service'
const props=defineProps({sid:[Number,String]}),emit=defineEmits(['changed']),router=useRouter(),available=ref(false),rows=ref([]),error=ref(''),busy=ref(false),leaderDialog=ref(false),selected=ref(null),leaderId=ref(null)
const labels={requested:'待审批',active:'参营中',ended:'已结束',rejected:'未通过'};let sequence=0
async function load(){const seq=++sequence;error.value='';try{if(!(await projectService.status()).enabled)return;available.value=true;const d=await projectService.campProjects(props.sid);if(seq===sequence)rows.value=d.projects}catch(e){if(seq===sequence&&available.value)error.value=e.response?.data?.message||'参营项目加载失败'}}
async function operate(row,action,leader){if(busy.value)return;let reason;try{reason=(await ElMessageBox.prompt('填写本次处理原因','项目参营',{inputValidator:v=>!!v?.trim()||'请填写原因'})).value}catch{return}busy.value=true;try{await projectService.operateCamp(row.project.id,row.binding.id,mutation(row.project,{action,reason,expected_binding_version:row.binding.version,user_ids:action==='participants'?((row.binding.change_pending&&!leader?row.binding.requested_users:row.binding.participants).map(m=>m.user_id)):undefined,leader_user_id:leader||undefined}));leaderDialog.value=false;await load();emit('changed');ElMessage.success('本期关联已更新')}catch(e){ElMessage.error(e.response?.data?.message||'处理失败')}finally{busy.value=false}}
function editLeader(row){selected.value=row;leaderId.value=row.binding.leader_user_id;leaderDialog.value=true}
function open(row){router.push({path:`/project-workspace/${row.project.id}`,query:{binding:row.binding.id,view:'camp',tab:'assessment',unit:row.binding.unit_id}})}
watch(()=>props.sid,()=>{rows.value=[];available.value=false;leaderDialog.value=false;load()},{immediate:true});onBeforeUnmount(()=>sequence++)
</script>
<style scoped>.project-camp-inbox{margin-bottom:26px;border-bottom:1px solid var(--dew-card-flat-border);padding-bottom:18px}.project-camp-inbox header{display:flex;align-items:center;justify-content:space-between}.project-camp-inbox h3{margin:0}.project-camp-inbox article{padding:10px 0}.project-camp-inbox h4{margin-bottom:5px}.pci-muted{color:var(--dew-text-muted);font-size:13px}</style>
